/**
 * Generate Jira issue browse URL from issue number.
 *
 * @param {string} issueNumber - The Jira issue number (e.g., "DHL-12345").
 * @returns {string} The full Jira issue URL.
 */
const getJiraIssueLink = (issueNumber) => `https://mvlchain.atlassian.net/browse/${issueNumber}`;

/**
 * Fetches the Jira issue number from a GitHub pull request.
 * It queries the GitHub API for the pull request information, extracts the issue number from the title,
 * and checks if it matches the Jira issue format.
 *
 * @returns {Promise<string|null>} The Jira issue number if found and valid, otherwise null.
 */
const getJiraIssueNumber = async () => {
  try {
    if (process.env.BRANCH_NAME) {
      try {
        console.info(`Found Branch Name ${process.env.BRANCH_NAME}`);
  
        const jiraIssueNumberFromBranch = /DEV\/([a-zA-Z]+\-[0-9]+).*/i.exec(process.env.BRANCH_NAME)?.[1];
  
        if (jiraIssueNumberFromBranch) {
          return jiraIssueNumberFromBranch;
        }
      } catch (e) {
        console.info('Error fetching Jira issue number from branch');
        console.info(e);
      }
    }

    console.info('Fetching Jira issue number from GitHub Pull Request...');

    const res = await fetch(`https://api.github.com/repos/${process.env.OWNER}/${process.env.REPO}/pulls/${process.env.GITHUB_PULL_REQUEST_NUMBER}`, {
      method: 'GET',
      headers: {
        Accept: 'application/vnd.github.v3+json',
        Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
        'Content-Type': 'application/json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
    });

    if (res.status !== 200) {
      throw await res.json();
    }

    console.info('Fetch GitHub Pull Request Success');
    
    const data = await res.json();
    
    console.info('Try `dhl xxxxx` format...');
    const issueNumber = /DHL (\d)+/i.exec(data.title)?.[1];
    
    if (issueNumber) {
      return `DHL-${issueNumber}`;
    }
    
    console.info('Try `DHL-xxxxx` format...');
    // title format = "[issuer number] [title]"
    const jiraIssueNumberFromTitle = data.title.split(' ')[0];

    if (!/^[a-zA-Z]+\-\d+$/.test(jiraIssueNumberFromTitle)) {
      return null;
    }

    return jiraIssueNumberFromTitle;
  } catch (error) {
    console.error('Error fetching Github issue');
    console.error(error);

    return null;
  }
};

/**
 * Fetches issue information from the Jira API.
 * It queries the Jira API for detailed information about a specific issue.
 *
 * @param {string} issueNumber - The Jira issue number.
 * @returns {Promise<Object|null>} The issue information if found, otherwise null.
 */
const getIssueInfo = async (issueNumber) => {
  try {
    console.info(`Fetching issue information from Jira for issue number: ${issueNumber}`);

    const res = await fetch(`https://mvlchain.atlassian.net/rest/api/2/issue/${issueNumber}?fields=summary,parent,issuelinks`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Basic ${process.env.JIRA_BASIC_CREDENTIALS}`,
      },
    });

    if (res.status !== 200) {
      throw await res.json();
    }

    const data = await res.json();

    if (!data?.fields) {
      return null;
    }

    return data.fields;
  } catch (error) {
    console.error('Error fetching Jira issue');
    console.error(error);

    return null;
  }
};

const CommentList = [
  async (fields, issueNumber) => {
    const commentParts = [];

    // Add main Jira issue link and title
    if (issueNumber) {
      commentParts.push(`### 📋 Jira Issue\n[${issueNumber}: ${fields.summary || '-'}](${getJiraIssueLink(issueNumber)})`);
    }

    // Add parent story issue if exists
    if (fields.parent?.fields && fields.parent?.key) {
      commentParts.push(
        `\n### 📖 Parent Issue\n[${fields.parent.key}: ${fields.parent.fields?.summary || '-'}](${getJiraIssueLink(fields.parent.key)})`
      );
    }

    // Add related issues if exist
    if ((fields.issuelinks?.length ?? 0) > 0) {
      const relatedLinks = [];

      fields.issuelinks.forEach((link) => {
        const linkedIssue = link.outwardIssue || link.inwardIssue;

        if (linkedIssue?.key) {
          relatedLinks.push(`- [${linkedIssue.key}: ${linkedIssue.fields?.summary || '-'}](${getJiraIssueLink(linkedIssue.key)})`);
        }
      });

      if (relatedLinks.length > 0) {
        commentParts.push(`\n### 🔗 Related Issues\n${relatedLinks.join('\n')}`);
      }
    }

    if (commentParts.length === 0) {
      return;
    }

    const commentBody = commentParts.join('\n');

    console.log(`Add Comment:\n${commentBody}`);

    await fetch(`https://api.github.com/repos/${process.env.OWNER}/${process.env.REPO}/issues/${process.env.GITHUB_PULL_REQUEST_NUMBER}/comments`, {
      method: 'POST',
      headers: {
        Accept: 'application/vnd.github.v3+json',
        Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
        'Content-Type': 'application/json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
      body: JSON.stringify({
        body: commentBody,
      }),
    });
  },
];

const addComments = async (...args) => {
  for (const fn of CommentList) {
    await fn(...args);
  }
};

const PRIORITY_PREFIX = 'priority_';
const ISSUE_TYPE_PREFIX = 'issue_type_';

/**
 * A collection of functions to extract specific labels from Jira issue fields.
 */
const targetLabel = [
  (fields) => fields.fixVersions?.map(({ name, releaseDate }) => `${name} / ${releaseDate}`),
  (fields) => fields.priority?.name && `${PRIORITY_PREFIX}${fields.priority.name.toLowerCase().replaceAll(' ', '_')}`,
  (fields) => fields.issuetype?.name && `${ISSUE_TYPE_PREFIX}${fields.issuetype.name.toLowerCase().replaceAll(' ', '_')}`,
  (fields) => fields.labels?.includes('QARequired') && 'qa_required',
];

/**
 * Color mapping for different labels.
 * default color: #CFD3D7
 */
const COLOR = {
  qa_required: 'ee0701',
  [`${PRIORITY_PREFIX}highest`]: 'ff5630',
  [`${PRIORITY_PREFIX}high`]: 'ff5630',
  [`${PRIORITY_PREFIX}medium`]: 'ffab00',
  [`${PRIORITY_PREFIX}low`]: '0065ff',
  [`${PRIORITY_PREFIX}lowest`]: '0065ff',
  [`${ISSUE_TYPE_PREFIX}스토리`]: '63ba3c',
  [`${ISSUE_TYPE_PREFIX}story`]: '63ba3c',
  [`${ISSUE_TYPE_PREFIX}디자인`]: 'f79232',
  [`${ISSUE_TYPE_PREFIX}design`]: 'f79232',
  [`${ISSUE_TYPE_PREFIX}개발`]: '4baee8',
  [`${ISSUE_TYPE_PREFIX}development`]: '4baee8',
  [`${ISSUE_TYPE_PREFIX}버그`]: 'e5493a',
  [`${ISSUE_TYPE_PREFIX}bug`]: 'e5493a',
  [`${ISSUE_TYPE_PREFIX}작업`]: '4bade8',
  [`${ISSUE_TYPE_PREFIX}task`]: '4bade8',
  [`${ISSUE_TYPE_PREFIX}하위_작업`]: '9da8b5',
  [`${ISSUE_TYPE_PREFIX}하위-작업`]: '9da8b5',
  [`${ISSUE_TYPE_PREFIX}sub_task`]: '9da8b5',
  [`${ISSUE_TYPE_PREFIX}sub-task`]: '9da8b5',
};

/**
 * Name mapping for different labels.
 */
const NAME = {
  qa_required: 'QARequired',
  [`${PRIORITY_PREFIX}highest`]: 'Priority: Highest',
  [`${PRIORITY_PREFIX}high`]: 'Priority: High',
  [`${PRIORITY_PREFIX}medium`]: 'Priority: Medium',
  [`${PRIORITY_PREFIX}low`]: 'Priority: Low',
  [`${PRIORITY_PREFIX}lowest`]: 'Priority: Lowest',
  [`${ISSUE_TYPE_PREFIX}스토리`]: 'Issue Type: Story',
  [`${ISSUE_TYPE_PREFIX}story`]: 'Issue Type: Story',
  [`${ISSUE_TYPE_PREFIX}디자인`]: 'Issue Type: Design',
  [`${ISSUE_TYPE_PREFIX}design`]: 'Issue Type: Design',
  [`${ISSUE_TYPE_PREFIX}개발`]: 'Issue Type: Development',
  [`${ISSUE_TYPE_PREFIX}development`]: 'Issue Type: Development',
  [`${ISSUE_TYPE_PREFIX}버그`]: 'Issue Type: Bug',
  [`${ISSUE_TYPE_PREFIX}bug`]: 'Issue Type: Bug',
  [`${ISSUE_TYPE_PREFIX}작업`]: 'Issue Type: 작업',
  [`${ISSUE_TYPE_PREFIX}task`]: 'Issue Type: 작업',
  [`${ISSUE_TYPE_PREFIX}하위_작업`]: 'Issue Type: 하위 작업',
  [`${ISSUE_TYPE_PREFIX}하위-작업`]: 'Issue Type: 하위 작업',
  [`${ISSUE_TYPE_PREFIX}sub_task`]: 'Issue Type: 하위 작업',
  [`${ISSUE_TYPE_PREFIX}sub-task`]: 'Issue Type: 하위 작업',
};

/**
 * Retrieves labels for a given Jira issue fields.
 * Processes the issue information through a series of functions to extract relevant labels.
 *
 * @async
 * @param {Object} fields - Jira issue fields.
 * @returns {Promise<Array<string>|null>} An array of labels if any, otherwise null.
 */
const getLabels = async (fields) => {
  const labels = targetLabel
    .flatMap((fn) => {
      const result = fn(fields);

      if (!result) {
        return null;
      }

      return Array.isArray(result) ? result : `${result}`;
    })
    .filter(Boolean);

  return labels;
};

/**
 * Checks if a label exists in the GitHub repository, and creates it if not.
 * It queries the GitHub API for each label and creates new labels as needed.
 *
 * @param {Array<string>} labels - The labels to check and create.
 */
const checkLabelExist = async (labels) => {
  console.info(`Checking and creating labels in GitHub repository: ${labels.map((label) => NAME[label] ?? label).join(', ')}`);

  for (const label of labels) {
    try {
      const res = await fetch(`https://api.github.com/repos/${process.env.OWNER}/${process.env.REPO}/labels/${NAME[label]}`, {
        method: 'GET',
        headers: {
          Accept: 'application/vnd.github.v3+json',
          Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
          'Content-Type': 'application/json',
          'X-GitHub-Api-Version': '2022-11-28',
        },
      });

      // Create new Label
      if (res.status === 404) {
        throw Error('Resource not found');
      }
    } catch (error) {
      console.log(label, NAME[label], COLOR[label]);

      await fetch(`https://api.github.com/repos/${process.env.OWNER}/${process.env.REPO}/labels`, {
        method: 'POST',
        headers: {
          Accept: 'application/vnd.github.v3+json',
          Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
          'Content-Type': 'application/json',
          'X-GitHub-Api-Version': '2022-11-28',
        },
        body: JSON.stringify({
          name: NAME[label] ?? label,
          color: COLOR[label] ?? 'cfd3d7',
        }),
      });
    }
  }
};

/**
 * Adds labels to a GitHub pull request.
 * It sends a request to the GitHub API to add labels to the specified pull request.
 *
 * @param {Array<string>} labels - The labels to be added to the pull request.
 */
const addLabel = async (labels) => {
  try {
    const data = labels.map((label) => NAME[label] ?? label);

    console.info(`Adding labels to GitHub Pull Request: ${data.join(', ')}`);

    const res = await fetch(
      `https://api.github.com/repos/${process.env.OWNER}/${process.env.REPO}/issues/${process.env.GITHUB_PULL_REQUEST_NUMBER}/labels`,
      {
        method: 'POST',
        headers: {
          Accept: 'application/vnd.github.v3+json',
          Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
          'Content-Type': 'application/json',
          'X-GitHub-Api-Version': '2022-11-28',
        },
        body: JSON.stringify({
          labels: data,
        }),
      }
    );

    console.info('===== Adding labels response =====');
    console.info(await res.json());
  } catch (error) {
    console.error('Error adding labels');
    console.error(error);
  }
};

const labelProcess = async (fields) => {
  const labels = await getLabels(fields);
  if (!labels || labels.length === 0) {
    console.info('No labels to process for this Jira issue.');
    return;
  }

  await checkLabelExist(labels);
  await addLabel(labels);
};

/**
 * Main function to run the script.
 * It orchestrates the process of fetching the Jira issue number, retrieving labels, checking their existence in GitHub,
 * and finally adding them to the pull request.
 */
async function run() {
  console.info('Starting the label processing script...');

  console.info('===== ENVIRONMENT VARIABLES =====');
  console.table({
    GITHUB_TOKEN: process.env.GITHUB_TOKEN,
    JIRA_BASIC_CREDENTIALS: process.env.JIRA_BASIC_CREDENTIALS,
    GITHUB_PULL_REQUEST_NUMBER: process.env.GITHUB_PULL_REQUEST_NUMBER,
    OWNER: process.env.OWNER,
    REPO: process.env.REPO,
    BRANCH_NAME: process.env.BRANCH_NAME,
  });

  const issueNumber = await getJiraIssueNumber();
  if (!issueNumber) {
    console.info('No valid Jira issue number found in GitHub Pull Request title.');
    console.info('Valid Format: /^([a-zA-Z]+\\-\\d+) .+$/');
    return;
  }

  console.info(`Found Jira issue number: ${issueNumber}`);

  const fields = await getIssueInfo(issueNumber);
  if (!fields) {
    return;
  }

  await Promise.all([addComments(fields, issueNumber), labelProcess(fields)]);
}

run();
